package api

// Source is intentionally implemented in several packages and both modules.
type Source interface { Read() string }
type ExtendedSource interface { Source; Close() error }
type Getter[T any] interface { Get() T }
type IntGetter = Getter[int]
type Missing interface { NeverImplemented() }

func Read(s Source) string { return s.Read() }
func GenericUse[G Getter[int]](g G) int { return g.Get() }

